import "fmt"

type array struct {
	data []int
	n    int
}

func (a *array) resize(c int) { b := make([]int, c); copy(b, a.data[:a.n]); a.data = b }
func (a *array) insert(i, v int) bool {
	if i < 0 || i > a.n {
		return false
	}
	if a.n == len(a.data) {
		c := 2 * len(a.data)
		if c == 0 {
			c = 1
		}
		a.resize(c)
	}
	for j := a.n; j > i; j-- {
		a.data[j] = a.data[j-1]
	}
	a.data[i] = v
	a.n++
	return true
}
func (a *array) remove(i int) (int, bool) {
	if i < 0 || i >= a.n {
		return 0, false
	}
	v := a.data[i]
	for j := i; j+1 < a.n; j++ {
		a.data[j] = a.data[j+1]
	}
	a.n--
	a.data[a.n] = 0
	if len(a.data) > 1 && a.n <= len(a.data)/4 {
		a.resize(len(a.data) / 2)
	}
	return v, true
}
func main() {
	a := array{}
	for _, x := range []int{4, 7, 9} {
		a.insert(a.n, x)
	}
	a.insert(1, 6)
	v, ok := a.remove(2)
	fmt.Println(a.data[:a.n], v, ok)
	_, ok = a.remove(9)
	fmt.Println(ok, a.n)
	for a.n > 0 {
		a.remove(a.n - 1)
	}
	fmt.Println(a.n, len(a.data))
}

