type Node struct {
	V    int
	Next *Node
}
type Queue struct{ Head, Tail *Node }

func (q *Queue) Push(v int) {
	n := &Node{V: v}
	if q.Tail == nil {
		q.Head = n
	} else {
		q.Tail.Next = n
	}
	q.Tail = n
}
func (q *Queue) Pop() (int, bool) {
	if q.Head == nil {
		return 0, false
	}
	v := q.Head.V
	q.Head = q.Head.Next
	if q.Head == nil {
		q.Tail = nil
	}
	return v, true
}
func main() {
	q := Queue{}
	q.Push(4)
	q.Push(7)
	fmt.Println(q.Pop())
	fmt.Println(q.Pop())
	fmt.Println(q.Head == nil, q.Tail == nil)
	q.Push(0)
	fmt.Println(q.Pop())
}

