type Queue struct {
	A          []int
	Head, Size int
}

func (q *Queue) Push(x int) bool {
	if q.Size == len(q.A) {
		return false
	}
	q.A[(q.Head+q.Size)%len(q.A)] = x
	q.Size++
	return true
}
func (q *Queue) Pop() (int, bool) {
	if q.Size == 0 {
		return 0, false
	}
	x := q.A[q.Head]
	q.Head = (q.Head + 1) % len(q.A)
	q.Size--
	return x, true
}
func main() {
	q := Queue{A: make([]int, 3)}
	q.Push(8)
	q.Push(9)
	q.Push(10)
	fmt.Println(q.Push(11))
	fmt.Println(q.Pop())
	q.Push(11)
	for q.Size > 0 {
		x, _ := q.Pop()
		fmt.Println(x)
	}
}

