func main() {
	a := make([]int, 4)
	head, size := 0, 0
	pushBack := func(x int) {
		if size == len(a) {
			panic("full")
		}
		a[(head+size)%len(a)] = x
		size++
	}
	pushFront := func(x int) {
		if size == len(a) {
			panic("full")
		}
		head = (head + len(a) - 1) % len(a)
		a[head] = x
		size++
	}
	pushBack(3)
	pushFront(2)
	pushBack(5)
	out := []int{}
	for i := 0; i < size; i++ {
		out = append(out, a[(head+i)%len(a)])
	}
	fmt.Println(out)
	last := a[(head+size-1)%len(a)]
	size--
	fmt.Println(last, size)
}

