import "fmt"

type Entry struct {
	Key, Value int
	State      uint8
}
type Table struct{ A []Entry }

func (t *Table) locate(k int) (int, bool) {
	free := -1
	for step := 0; step < len(t.A); step++ {
		i := (k%len(t.A) + step) % len(t.A)
		e := t.A[i]
		if e.State == 1 && e.Key == k {
			return i, true
		}
		if e.State != 1 && free < 0 {
			free = i
		}
		if e.State == 0 {
			break
		}
	}
	return free, false
}
func (t *Table) put(k, v int) bool {
	i, _ := t.locate(k)
	if i < 0 {
		return false
	}
	t.A[i] = Entry{k, v, 1}
	return true
}
func (t *Table) get(k int) (int, bool) {
	i, ok := t.locate(k)
	if !ok {
		return 0, false
	}
	return t.A[i].Value, true
}
func (t *Table) remove(k int) {
	i, ok := t.locate(k)
	if ok {
		t.A[i].State = 2
	}
}
func main() {
	t := Table{A: make([]Entry, 4)}
	t.put(1, 10)
	t.put(5, 50)
	t.remove(1)
	fmt.Println(t.get(5))
	t.put(5, 51)
	fmt.Println(t.get(5))
	t.put(9, 90)
	fmt.Println(t.get(9))
}

