import "fmt"

type table struct {
	k    []int
	used []bool
}

func newTable(n int) *table { return &table{k: make([]int, n), used: make([]bool, n)} }
func (t *table) find(k int) int {
	if len(t.k) == 0 || k < 0 {
		return -1
	}
	for s := 0; s < len(t.k); s++ {
		i := (k%len(t.k) + s) % len(t.k)
		if !t.used[i] {
			return -1
		}
		if t.k[i] == k {
			return i
		}
	}
	return -1
}
func (t *table) put(k int) bool {
	if len(t.k) == 0 || k < 0 {
		return false
	}
	for s := 0; s < len(t.k); s++ {
		i := (k%len(t.k) + s) % len(t.k)
		if !t.used[i] || t.k[i] == k {
			t.k[i] = k
			t.used[i] = true
			return true
		}
	}
	return false
}
func (t *table) remove(k int) bool {
	i := t.find(k)
	if i < 0 {
		return false
	}
	t.used[i] = false
	for j := (i + 1) % len(t.k); t.used[j]; j = (j + 1) % len(t.k) {
		v := t.k[j]
		t.used[j] = false
		t.put(v)
	}
	return true
}
func main() {
	t := newTable(5)
	for _, k := range []int{0, 5, 10} {
		t.put(k)
	}
	fmt.Println(t.remove(0), t.find(5) >= 0, t.find(10) >= 0, t.find(0) >= 0)
	u := newTable(3)
	for _, k := range []int{0, 3, 6} {
		u.put(k)
	}
	fmt.Println(u.remove(3), u.find(0) >= 0, u.find(6) >= 0, u.put(9))
}

