import "fmt"

type Node struct {
	K, H int
	L, R *Node
}

func h(n *Node) int {
	if n == nil {
		return 0
	}
	return n.H
}
func fix(n *Node) { n.H = 1 + max(h(n.L), h(n.R)) }
func right(y *Node) *Node {
	x := y.L
	middle := x.R
	x.R = y
	y.L = middle
	fix(y)
	fix(x)
	return x
}
func inorder(n *Node, out *[]int) {
	if n == nil {
		return
	}
	inorder(n.L, out)
	*out = append(*out, n.K)
	inorder(n.R, out)
}
func main() {
	a := &Node{K: 1, H: 1}
	b := &Node{K: 2, H: 2, L: a}
	root := &Node{K: 3, H: 3, L: b}
	root = right(root)
	out := []int{}
	inorder(root, &out)
	fmt.Println(root.K, root.H, out)
}

