import "fmt"

type Node struct {
	K    int
	L, R *Node
}

func put(n *Node, k int) *Node {
	if n == nil {
		return &Node{K: k}
	}
	if k < n.K {
		n.L = put(n.L, k)
	} else if k > n.K {
		n.R = put(n.R, k)
	}
	return n
}
func remove(n *Node, k int) *Node {
	if n == nil {
		return nil
	}
	if k < n.K {
		n.L = remove(n.L, k)
	} else if k > n.K {
		n.R = remove(n.R, k)
	} else {
		if n.L == nil {
			return n.R
		}
		if n.R == nil {
			return n.L
		}
		p := n.R
		for p.L != nil {
			p = p.L
		}
		n.K = p.K
		n.R = remove(n.R, p.K)
	}
	return n
}
func collect(n *Node, a *[]int) {
	if n == nil {
		return
	}
	collect(n.L, a)
	*a = append(*a, n.K)
	collect(n.R, a)
}
func main() {
	var root *Node
	for _, k := range []int{4, 2, 6, 5, 7} {
		root = put(root, k)
	}
	root = remove(root, 4)
	a := []int{}
	collect(root, &a)
	fmt.Println(a)
	root = remove(root, 99)
	a = nil
	collect(root, &a)
	fmt.Println(a)
}

