func bubble(a []int) {
	for end := len(a) - 1; end > 0; end-- {
		changed := false
		for i := 0; i < end; i++ {
			if a[i] > a[i+1] {
				a[i], a[i+1] = a[i+1], a[i]
				changed = true
			}
		}
		if !changed {
			return
		}
	}
}
func main() {
	a := []int{3, 1, 2}
	bubble(a)
	fmt.Println(a)
	b := []int{2, 2, 1}
	bubble(b)
	fmt.Println(b)
}

