import "fmt"

func shell(a []int) {
	for gap := len(a) / 2; gap > 0; gap /= 2 {
		for i := gap; i < len(a); i++ {
			x, j := a[i], i
			for j >= gap && a[j-gap] > x {
				a[j] = a[j-gap]
				j -= gap
			}
			a[j] = x
		}
	}
}
func main() { a := []int{8, 5, 3, 1, 6, 2}; shell(a); fmt.Println(a) }

