func quick(a []int) []int {
	if len(a) < 2 {
		return append([]int(nil), a...)
	}
	pivot := a[len(a)/2]
	lo, eq, hi := []int{}, []int{}, []int{}
	for _, x := range a {
		if x < pivot {
			lo = append(lo, x)
		} else if x > pivot {
			hi = append(hi, x)
		} else {
			eq = append(eq, x)
		}
	}
	out := append(quick(lo), eq...)
	return append(out, quick(hi)...)
}
