import "fmt"

func down(a []int, i, n int) {
	for {
		j := 2*i + 1
		if j >= n {
			return
		}
		if j+1 < n && a[j+1] > a[j] {
			j++
		}
		if a[i] >= a[j] {
			return
		}
		a[i], a[j] = a[j], a[i]
		i = j
	}
}
func heapsort(a []int) {
	for i := len(a)/2 - 1; i >= 0; i-- {
		down(a, i, len(a))
	}
	for end := len(a) - 1; end > 0; end-- {
		a[0], a[end] = a[end], a[0]
		down(a, 0, end)
	}
}
func main() { a := []int{3, 1, 4, 2}; heapsort(a); fmt.Println(a); heapsort(nil) }

