import "fmt"

func radix(a []int) {
	mx := 0
	for _, x := range a {
		if x < 0 {
			panic("negative")
		}
		mx = max(mx, x)
	}
	out := make([]int, len(a))
	for exp := 1; mx/exp > 0; {
		var count [10]int
		for _, x := range a {
			count[x/exp%10]++
		}
		start := 0
		for d, n := range count {
			count[d] = start
			start += n
		}
		for _, x := range a {
			d := x / exp % 10
			out[count[d]] = x
			count[d]++
		}
		copy(a, out)
		if exp > mx/10 {
			break
		}
		exp *= 10
	}
}
func main() {
	a := []int{21, 13, 12, 23}
	radix(a)
	fmt.Println(a)
	z := []int{0, 0}
	radix(z)
	fmt.Println(z)
}

