func main() {
	parent := []int{0, 1, 2, 3}
	size := []int{1, 1, 1, 1}
	find := func(x int) int {
		for x != parent[x] {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	union := func(a, b int) {
		a, b = find(a), find(b)
		if a == b {
			return
		}
		if size[a] < size[b] {
			a, b = b, a
		}
		parent[b] = a
		size[a] += size[b]
	}
	union(0, 1)
	union(2, 3)
	fmt.Println(find(0) == find(3))
	union(1, 2)
	fmt.Println(find(0) == find(3))
