type Trie struct {
	End  bool
	Next map[rune]*Trie
}

func (t *Trie) insert(s string) {
	for _, r := range s {
		if t.Next == nil {
			t.Next = map[rune]*Trie{}
		}
		if t.Next[r] == nil {
			t.Next[r] = &Trie{}
		}
		t = t.Next[r]
	}
	t.End = true
}
func (t *Trie) search(s string) bool {
	for _, r := range s {
		t = t.Next[r]
		if t == nil {
			return false
		}
	}
	return t.End
}
