func shortest(a []int, target int) int {
	left, sum, best := 0, 0, len(a)+1
	for right, x := range a {
		sum += x
		for sum >= target && left <= right {
			best = min(best, right-left+1)
			sum -= a[left]
			left++
		}
	}
	if best > len(a) {
		return 0
	}
	return best
}
