func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
func solve(a []int) int {
	if len(a) == 1 {
		return a[0]
	}
	m := len(a) / 2
	best := max(solve(a[:m]), solve(a[m:]))
	sum, left := 0, a[m-1]
	for i := m - 1; i >= 0; i-- {
		sum += a[i]
		left = max(left, sum)
	}
	sum, right := 0, a[m]
	for i := m; i < len(a); i++ {
		sum += a[i]
		right = max(right, sum)
	}
	return max(best, left+right)
}
