	}
	return r
}
func gcd(a, b uint64) uint64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
func lcm(a, b uint64) (uint64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	q := a / gcd(a, b)
	if q > ^uint64(0)/b {
		return 0, false
	}
	return q * b, true
}
func main() {
