func root(n uint64) uint64 {
	lo, hi := uint64(0), n
	var ans uint64
	for lo <= hi {
		m := lo + (hi-lo)/2
		if m == 0 || m <= n/m {
			ans = m
			if m == n {
				break
			}
			lo = m + 1
		} else {
			hi = m - 1
		}
	}
