func sentences(s string, words []string) []string {
	dict := []string{}
	seenWord := map[string]bool{}
	for _, w := range words {
		if w != "" && !seenWord[w] {
			dict = append(dict, w)
			seenWord[w] = true
		}
	}
	memo := map[int][]string{}
	var solve func(int) []string
	solve = func(i int) []string {
		if i == len(s) {
			return []string{""}
		}
		if v, ok := memo[i]; ok {
			return v
		}
		out := []string{}
		for _, w := range dict {
			if strings.HasPrefix(s[i:], w) {
				for _, tail := range solve(i + len(w)) {
					v := w
					if tail != "" {
						v += " " + tail
					}
					out = append(out, v)
				}
			}
		}
		memo[i] = out
		return out
	}
	return solve(0)
}
