const neg = -int(^uint(0)>>1) / 4

func cooldown(a []int) int {
	h, s, r := neg, neg, 0
	for _, p := range a {
		h, s, r = max(h, r-p), h+p, max(r, s)
	}
	return max(r, s)
}
func limited(a []int, k int) int {
	if k <= 0 {
		return 0
	}
	if k > len(a)/2 {
		k = len(a) / 2
	}
	c, h := make([]int, k+1), make([]int, k+1)
	for j := range h {
		h[j] = neg
	}
	for _, p := range a {
		nc, nh := append([]int(nil), c...), append([]int(nil), h...)
		for j := 1; j <= k; j++ {
			nc[j] = max(c[j], h[j]+p)
			nh[j] = max(h[j], c[j-1]-p)
		}
		c, h = nc, nh
	}
	return c[k]
}
