func solve(b [][]byte) bool {
	if len(b) != 9 {
		return false
	}
	var rows, cols, boxes [9]int
	for r := 0; r < 9; r++ {
		if len(b[r]) != 9 {
			return false
		}
		for c, v := range b[r] {
			if v == '.' {
				continue
			}
			if v < '1' || v > '9' {
				return false
			}
			bit := 1 << uint(v-'1')
			box := r/3*3 + c/3
			if (rows[r]|cols[c]|boxes[box])&bit != 0 {
				return false
			}
			rows[r] |= bit
			cols[c] |= bit
			boxes[box] |= bit
		}
	}
	var search func(int) bool
	search = func(pos int) bool {
		if pos == 81 {
			return true
		}
		r, c := pos/9, pos%9
		if b[r][c] != '.' {
			return search(pos + 1)
		}
		box := r/3*3 + c/3
		for d := 0; d < 9; d++ {
			bit := 1 << uint(d)
			if (rows[r]|cols[c]|boxes[box])&bit != 0 {
				continue
			}
			b[r][c] = byte('1' + d)
			rows[r] |= bit
			cols[c] |= bit
			boxes[box] |= bit
			if search(pos + 1) {
				return true
			}
			rows[r] &^= bit
			cols[c] &^= bit
			boxes[box] &^= bit
			b[r][c] = '.'
		}
		return false
	}
	return search(0)
}
func main() {
	texts := []string{".34678912", "672195348", "198342567", "859761423", "426853791", "713924856", "961537284", "287419635", "345286179"}
	b := [][]byte{}
	for _, s := range texts {
		b = append(b, []byte(s))
	}
	fmt.Println(solve(b), string(b[0]))
	b[0][0] = '3'
	fmt.Println(solve(b))
}

