func partition(a []int, k int) bool {
	if k <= 0 || k > len(a) {
		return false
	}
	sum := 0
	for _, x := range a {
		if x < 0 {
			return false
		}
		sum += x
	}
	if sum%k != 0 {
		return false
	}
	target := sum / k
	if target == 0 {
		return true
	}
	a = append([]int(nil), a...)
	sort.Sort(sort.Reverse(sort.IntSlice(a)))
	b := make([]int, k)
	var place func(int) bool
	place = func(i int) bool {
		if i == len(a) {
			return true
		}
		seen := map[int]bool{}
		for j := range b {
			if seen[b[j]] || b[j]+a[i] > target {
				continue
			}
			seen[b[j]] = true
			b[j] += a[i]
			if place(i + 1) {
				return true
			}
			b[j] -= a[i]
		}
		return false
	}
	return place(0)
}
func main() {
	fmt.Println(partition([]int{4, 3, 2, 3, 5, 2, 1}, 4), partition([]int{1, 2, 4}, 2), partition([]int{0, 0}, 2))
