func islands(a [][]int) int {
	if len(a) == 0 {
		return 0
	}
	rows, cols := len(a), len(a[0])
	dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	var visit func(int, int)
	visit = func(r, c int) {
		a[r][c] = 0
		for _, d := range dirs {
			nr, nc := r+d[0], c+d[1]
			if nr >= 0 && nr < rows && nc >= 0 && nc < cols && a[nr][nc] == 1 {
				visit(nr, nc)
			}
		}
	}
	n := 0
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if a[r][c] == 1 {
				n++
				visit(r, c)
			}
		}
	}
	return n
}
func main() { fmt.Println(islands([][]int{{1, 0, 1}, {1, 0, 1}})) }

