import "fmt"

func bipartite(g [][]int) bool {
	color := make([]int, len(g))
	for s := range g {
		if color[s] != 0 {
			continue
		}
		color[s] = 1
		q := []int{s}
		for h := 0; h < len(q); h++ {
			v := q[h]
			for _, w := range g[v] {
				if color[w] == 0 {
					color[w] = -color[v]
					q = append(q, w)
				} else if color[w] == color[v] {
					return false
				}
			}
		}
	}
	return true
}
func main() {
	fmt.Println(bipartite([][]int{{1, 2}, {0, 2}, {0, 1}}), bipartite([][]int{{1}, {0}, {}}))
}

