type Edge struct{ U, V, W int }

func shortest(n int, es []Edge) ([]int, bool) {
	const inf = 1000000
	d := make([]int, n)
	for i := range d {
		d[i] = inf
	}
	d[0] = 0
	for k := 0; k < n-1; k++ {
		next := append([]int(nil), d...)
		for _, e := range es {
			if d[e.U] != inf {
				next[e.V] = min(next[e.V], d[e.U]+e.W)
			}
		}
		d = next
	}
	for _, e := range es {
		if d[e.U] != inf && d[e.U]+e.W < d[e.V] {
			return d, false
		}
	}
	return d, true
}
func main() {
	d, ok := shortest(3, []Edge{{0, 1, 2}, {0, 2, 5}, {2, 1, -10}})
	fmt.Println(d, ok)
	_, ok = shortest(2, []Edge{{0, 1, 1}, {1, 0, -2}})
	fmt.Println(ok)
}

