func cycle(g [][]int) bool {
	c := make([]int, len(g))
	var dfs func(int) bool
	dfs = func(v int) bool {
		c[v] = 1
		for _, w := range g[v] {
			if c[w] == 1 {
				return true
			}
			if c[w] == 0 && dfs(w) {
				return true
			}
		}
		c[v] = 2
		return false
	}
	for v := range g {
		if c[v] == 0 && dfs(v) {
			return true
		}
	}
	return false
}
func main() {
	fmt.Println(cycle([][]int{{1, 2}, {3}, {3}, {}}), cycle([][]int{{1}, {2}, {0}}), cycle([][]int{{}, {2}, {1}}), cycle([][]int{{0}}))
}

