import "fmt"

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
func astar(a [][]int) int {
	if len(a) == 0 || len(a[0]) == 0 {
		return -1
	}
	m, n := len(a), len(a[0])
	for _, r := range a {
		if len(r) != n {
			return -1
		}
	}
	if a[0][0] != 0 || a[m-1][n-1] != 0 {
		return -1
	}
	d := make([]int, m*n)
	closed := make([]bool, m*n)
	for i := range d {
		d[i] = -1
	}
	d[0] = 0
	for {
		v := -1
		best := int(^uint(0) >> 1)
		for x := range d {
			if d[x] >= 0 && !closed[x] {
				f := d[x] + abs(m-1-x/n) + abs(n-1-x%n)
				if f < best {
					v, best = x, f
				}
			}
		}
		if v < 0 {
			return -1
		}
		if v == m*n-1 {
			return d[v]
		}
		closed[v] = true
		r, c := v/n, v%n
		for _, step := range [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}} {
			rr, cc := r+step[0], c+step[1]
			if rr < 0 || rr >= m || cc < 0 || cc >= n || a[rr][cc] != 0 {
				continue
			}
			w := rr*n + cc
			if !closed[w] && (d[w] < 0 || d[v]+1 < d[w]) {
				d[w] = d[v] + 1
			}
		}
	}
}
func main() {
	fmt.Println(astar([][]int{{0, 0, 0}, {0, 1, 0}, {0, 0, 0}}), astar([][]int{{0, 1}, {1, 0}}), astar([][]int{{0}}))
}

