type edge struct{ a, b, w int }

func shortest(n int, edges []edge, src, dst, k int) int {
	const inf = int(^uint(0)>>1) / 4
	d := make([]int, n)
	for i := range d {
		d[i] = inf
	}
	d[src] = 0
	for s := 0; s < k; s++ {
		next := append([]int(nil), d...)
		for _, e := range edges {
			if d[e.a] != inf && d[e.a]+e.w < next[e.b] {
				next[e.b] = d[e.a] + e.w
			}
		}
		d = next
	}
	if d[dst] == inf {
		return -1
	}
	return d[dst]
}
func main() {
	e := []edge{{0, 1, 5}, {0, 2, 1}, {2, 1, 1}, {1, 3, 1}}
	fmt.Println(shortest(4, e, 0, 3, 2), shortest(4, e, 0, 3, 3), shortest(4, e, 0, 3, 0), shortest(4, e, 0, 0, 0))
}

