import "fmt"

func index(text, pattern string) int {
	if len(pattern) == 0 {
		return 0
	}
	pi := make([]int, len(pattern))
	for i, j := 1, 0; i < len(pattern); i++ {
		for j > 0 && pattern[i] != pattern[j] {
			j = pi[j-1]
		}
		if pattern[i] == pattern[j] {
			j++
		}
		pi[i] = j
	}
	for i, j := 0, 0; i < len(text); i++ {
		for j > 0 && text[i] != pattern[j] {
			j = pi[j-1]
		}
		if text[i] == pattern[j] {
			j++
		}
		if j == len(pattern) {
			return i - j + 1
		}
	}
	return -1
}
func main() { fmt.Println(index("zzababac", "ababa"), index("abc", "x"), index("abc", "")) }

