import "fmt"

func find(s, p string) int {
	m := len(p)
	if m == 0 {
		return 0
	}
	if m > len(s) {
		return -1
	}
	const base, mod int64 = 31, 101
	power := int64(1)
	for i := 1; i < m; i++ {
		power = power * base % mod
	}
	hp, h := int64(0), int64(0)
	for i := 0; i < m; i++ {
		hp = (hp*base + int64(p[i])) % mod
		h = (h*base + int64(s[i])) % mod
	}
	for l := 0; ; l++ {
		if h == hp && s[l:l+m] == p {
			return l
		}
		if l+m == len(s) {
			break
		}
		h = (h - int64(s[l])*power%mod + mod) % mod
		h = (h*base + int64(s[l+m])) % mod
	}
	return -1
}
func main() { fmt.Println(find("cabdab", "ab"), find("abc", "abcd")) }

