type Frame struct {
	N        *Node
	Expanded bool
}

func main() {
	root := &Node{2, &Node{V: 1}, &Node{V: 3}}
	stack := []Frame{{root, false}}
	out := []int{}
	for len(stack) > 0 {
		f := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if f.N == nil {
			continue
		}
		if f.Expanded {
			out = append(out, f.N.V)
		} else {
			stack = append(stack, Frame{f.N, true}, Frame{f.N.R, false}, Frame{f.N.L, false})
		}
	}
