type Node struct{ L, R *Node }

func count(n *Node) int {
	if n == nil {
		return 0
	}
	l, r := 0, 0
	for p := n; p != nil; p = p.L {
		l++
	}
	for p := n; p != nil; p = p.R {
		r++
	}
	if l == r {
		return (1 << uint(l)) - 1
	}
	return 1 + count(n.L) + count(n.R)
}
func main() {
	a := make([]*Node, 6)
	for i := range a {
		a[i] = &Node{}
	}
	for i := range a {
		if 2*i+1 < len(a) {
			a[i].L = a[2*i+1]
		}
		if 2*i+2 < len(a) {
			a[i].R = a[2*i+2]
		}
	}
	fmt.Println(count(a[0]), count(nil))
}

