import "fmt"

type Node struct {
	K    int
	L, R *Node
}

func build(pre, in []int) (*Node, bool) {
	if len(pre) != len(in) {
		return nil, false
	}
	pos := map[int]int{}
	for i, x := range in {
		if _, ok := pos[x]; ok {
			return nil, false
		}
		pos[x] = i
	}
	next := 0
	var rec func(int, int) (*Node, bool)
	rec = func(l, r int) (*Node, bool) {
		if l == r {
			return nil, true
		}
		if next >= len(pre) {
			return nil, false
		}
		x := pre[next]
		next++
		m, ok := pos[x]
		if !ok || m < l || m >= r {
			return nil, false
		}
		a, ok := rec(l, m)
		if !ok {
			return nil, false
		}
		b, ok := rec(m+1, r)
		if !ok {
			return nil, false
		}
		return &Node{x, a, b}, true
	}
	root, ok := rec(0, len(in))
	return root, ok && next == len(pre)
}
func post(n *Node, a *[]int) {
	if n == nil {
		return
	}
	post(n.L, a)
	post(n.R, a)
	*a = append(*a, n.K)
}
func main() {
	root, ok := build([]int{2, 1, 3}, []int{1, 2, 3})
	a := []int{}
	post(root, &a)
	fmt.Println(a, ok)
	_, ok = build([]int{2, 1}, []int{2, 2})
	fmt.Println(ok)
}

