import (
	"fmt"
	"strconv"
	"strings"
)

type Node struct {
	K    int
	L, R *Node
}

func encode(n *Node) string {
	if n == nil {
		return "#"
	}
	return strconv.Itoa(n.K) + "," + encode(n.L) + "," + encode(n.R)
}
func decode(s string) (*Node, error) {
	ts := strings.Split(s, ",")
	i := 0
	var rec func() (*Node, error)
	rec = func() (*Node, error) {
		if i == len(ts) {
			return nil, fmt.Errorf("missing token")
		}
		v := ts[i]
		i++
		if v == "#" {
			return nil, nil
		}
		k, e := strconv.Atoi(v)
		if e != nil {
			return nil, e
		}
		l, e := rec()
		if e != nil {
			return nil, e
		}
		r, e := rec()
		if e != nil {
			return nil, e
		}
		return &Node{k, l, r}, nil
	}
	root, e := rec()
	if e == nil && i != len(ts) {
		e = fmt.Errorf("extra token")
	}
	return root, e
}
func main() {
	s := encode(&Node{K: 2, L: &Node{K: -1}})
	n, e := decode(s)
	fmt.Println(s, encode(n) == s, e == nil)
	_, e = decode("1,#")
	fmt.Println(e != nil)
	_, e = decode("#,#")
	fmt.Println(e != nil)
}

