import "fmt"

type Trie struct {
	End  bool
	Next map[rune]*Trie
}

func (t *Trie) put(s string) {
	for _, r := range s {
		if t.Next == nil {
			t.Next = map[rune]*Trie{}
		}
		if t.Next[r] == nil {
			t.Next[r] = &Trie{}
		}
		t = t.Next[r]
	}
	t.End = true
}
func (t *Trie) node(s string) *Trie {
	for _, r := range s {
		t = t.Next[r]
		if t == nil {
			return nil
		}
	}
	return t
}
func (t *Trie) match(a []rune, i int) bool {
	if i == len(a) {
		return t.End
	}
	if a[i] != '.' {
		n := t.Next[a[i]]
		return n != nil && n.match(a, i+1)
	}
	for _, n := range t.Next {
		if n.match(a, i+1) {
			return true
		}
	}
	return false
}
func erase(t *Trie, a []rune, i int) bool {
	if i == len(a) {
		t.End = false
	} else if n := t.Next[a[i]]; n != nil {
		if erase(n, a, i+1) {
			delete(t.Next, a[i])
		}
	}
	return !t.End && len(t.Next) == 0
}
func main() {
	t := &Trie{}
	for _, s := range []string{"go", "gone", "gut"} {
		t.put(s)
	}
	fmt.Println(t.match([]rune("g."), 0))
	erase(t, []rune("go"), 0)
	fmt.Println(t.node("go").End, t.node("gone").End, t.node("go") != nil)
}

