import "fmt"

func solve(a []int) ([]int, int) {
	if len(a) < 2 {
		return append([]int(nil), a...), 0
	}
	m := len(a) / 2
	l, x := solve(a[:m])
	r, y := solve(a[m:])
	out := []int{}
	i, j, count := 0, 0, x+y
	for i < len(l) && j < len(r) {
		if l[i] <= r[j] {
			out = append(out, l[i])
			i++
		} else {
			count += len(l) - i
			out = append(out, r[j])
			j++
		}
	}
	out = append(out, l[i:]...)
	out = append(out, r[j:]...)
	return out, count
}
func main() {
	a, n := solve([]int{2, 4, 1, 3})
	fmt.Println(a, n)
	_, n = solve([]int{2, 2})
	fmt.Println(n)
}

