import "fmt"

func selectK(a []int, k int) int {
	if k < 0 || k >= len(a) {
		panic("rank")
	}
	l, r := 0, len(a)
	for l < r {
		pivot := a[l+(r-l)/2]
		lt, i, gt := l, l, r
		for i < gt {
			if a[i] < pivot {
				a[lt], a[i] = a[i], a[lt]
				lt++
				i++
			} else if a[i] > pivot {
				gt--
				a[gt], a[i] = a[i], a[gt]
			} else {
				i++
			}
		}
		if k < lt {
			r = lt
		} else if k >= gt {
			l = gt
		} else {
			return pivot
		}
	}
	panic("unreachable")
}
func main() { fmt.Println(selectK([]int{5, 1, 4, 2, 3}, 2), selectK([]int{2, 2, 1}, 1)) }

