type Queue struct{ In, Out []int }

func (q *Queue) Push(x int) { q.In = append(q.In, x) }
func (q *Queue) Pop() (int, bool) {
	if len(q.Out) == 0 {
		for len(q.In) > 0 {
			i := len(q.In) - 1
			q.Out = append(q.Out, q.In[i])
			q.In = q.In[:i]
		}
	}
	if len(q.Out) == 0 {
		return 0, false
	}
	i := len(q.Out) - 1
	x := q.Out[i]
	q.Out = q.Out[:i]
	return x, true
}
func main() {
	q := Queue{}
	q.Push(1)
	q.Push(2)
	fmt.Println(q.Pop())
	q.Push(3)
	fmt.Println(q.Pop())
	fmt.Println(q.Pop())
	fmt.Println(q.Pop())
}

