func maxima(a []int, k int) []int {
	if k <= 0 || k > len(a) {
		return []int{}
	}
	q := []int{}
	out := []int{}
	for i, x := range a {
		for len(q) > 0 && q[0] <= i-k {
			q = q[1:]
		}
		for len(q) > 0 && a[q[len(q)-1]] <= x {
			q = q[:len(q)-1]
		}
		q = append(q, i)
		if i >= k-1 {
			out = append(out, a[q[0]])
		}
	}
	return out
}
func main() { fmt.Println(maxima([]int{1, 3, 2, 5}, 2), maxima([]int{2, 2, 1}, 2), maxima(nil, 1)) }

