)

type Event struct{ Time, Delta int }

func peak(intervals [][2]int) int {
	es := []Event{}
	for _, p := range intervals {
		if p[0] >= p[1] {
			continue
		}
		es = append(es, Event{p[0], 1}, Event{p[1], -1})
	}
	sort.Slice(es, func(i, j int) bool {
		if es[i].Time != es[j].Time {
			return es[i].Time < es[j].Time
		}
		return es[i].Delta < es[j].Delta
	})
	active, best := 0, 0
	for _, e := range es {
		active += e.Delta
		best = max(best, active)
	}
	return best
}
func main() { fmt.Println(peak([][2]int{{1, 3}, {2, 4}, {3, 5}}), peak([][2]int{{0, 1}, {1, 2}})) }

