	"sort"
)

func sums(a []int, start, k, target int) [][]int {
	out := [][]int{}
	if k < 2 || len(a)-start < k {
		return out
	}
	if k == 2 {
		for l, r := start, len(a)-1; l < r; {
			s := a[l] + a[r]
			if s < target {
				l++
			} else if s > target {
				r--
			} else {
				x, y := a[l], a[r]
				out = append(out, []int{x, y})
				for l < r && a[l] == x {
					l++
				}
				for l < r && a[r] == y {
					r--
				}
			}
		}
		return out
	}
	for i := start; i <= len(a)-k; i++ {
		if i > start && a[i] == a[i-1] {
			continue
		}
		for _, tail := range sums(a, i+1, k-1, target-a[i]) {
			row := append([]int{a[i]}, tail...)
			out = append(out, row)
		}
	}
	return out
}
func main() {
	a := []int{-2, -1, 0, 1, 2}
	sort.Ints(a)
	fmt.Println(sums(a, 0, 3, 0))
	fmt.Println(sums([]int{0, 0, 0, 0}, 0, 3, 0))
}

