import "fmt"

type node struct {
	k    int
	red  bool
	l, r *node
}

func red(n *node) bool { return n != nil && n.red }
func left(h *node) *node {
	x := h.r
	h.r = x.l
	x.l = h
	x.red = h.red
	h.red = true
	return x
}
func right(h *node) *node {
	x := h.l
	h.l = x.r
	x.r = h
	x.red = h.red
	h.red = true
	return x
}
func insert(h *node, k int) *node {
	if h == nil {
		return &node{k: k, red: true}
	}
	if k < h.k {
		h.l = insert(h.l, k)
	} else if k > h.k {
		h.r = insert(h.r, k)
	}
	if red(h.r) && !red(h.l) {
		h = left(h)
	}
	if red(h.l) && red(h.l.l) {
		h = right(h)
	}
	if red(h.l) && red(h.r) {
		h.red = !h.red
		h.l.red = !h.l.red
		h.r.red = !h.r.red
	}
	return h
}
func check(h *node, lo, hi *int) (int, bool) {
	if h == nil {
		return 1, true
	}
	if lo != nil && h.k <= *lo || hi != nil && h.k >= *hi || red(h.r) || red(h) && red(h.l) {
		return 0, false
	}
	a, ok := check(h.l, lo, &h.k)
	b, ok2 := check(h.r, &h.k, hi)
	if !ok || !ok2 || a != b {
		return 0, false
	}
	if !h.red {
		a++
	}
	return a, true
}
func main() {
	var root *node
	for i := 1; i <= 100; i++ {
		root = insert(root, i)
		root.red = false
		_, ok := check(root, nil, nil)
		if !ok {
			panic("invalid tree")
		}
	}
	root = insert(root, 50)
	root.red = false
	_, ok := check(root, nil, nil)
	a := []int{}
	var walk func(*node)
	walk = func(n *node) {
		if n != nil {
			walk(n.l)
			a = append(a, n.k)
			walk(n.r)
		}
	}
	walk(root)
	fmt.Println(ok, len(a), a[0], a[len(a)-1])
}

