import "fmt"

type node struct {
	v    int
	l, r *node
}

func lca(root, p, q *node) *node {
	if p == nil || q == nil {
		return nil
	}
	var visit func(*node) (int, *node)
	visit = func(n *node) (int, *node) {
		if n == nil {
			return 0, nil
		}
		a, x := visit(n.l)
		b, y := visit(n.r)
		mask := a | b
		if n == p {
			mask |= 1
		}
		if n == q {
			mask |= 2
		}
		if x != nil {
			return mask, x
		}
		if y != nil {
			return mask, y
		}
		if mask == 3 {
			return mask, n
		}
		return mask, nil
	}
	mask, n := visit(root)
	if mask != 3 {
		return nil
	}
	return n
}
func main() {
	a, b := &node{v: 4}, &node{v: 5}
	p := &node{v: 2, l: a, r: b}
	root := &node{v: 1, l: p, r: &node{v: 3}}
	fmt.Println(lca(root, a, b).v, lca(root, p, a).v, lca(root, a, a).v, lca(root, a, &node{v: 4}) == nil)
}

