import "fmt"

type node struct {
	sum  int64
	l, r *node
}

const size = 1_000_000_000

func sum(n *node) int64 {
	if n == nil {
		return 0
	}
	return n.sum
}
func add(n **node, lo, hi, x int, v int64) {
	if *n == nil {
		*n = &node{}
	}
	if hi-lo == 1 {
		(*n).sum += v
		return
	}
	m := lo + (hi-lo)/2
	if x < m {
		add(&(*n).l, lo, m, x, v)
	} else {
		add(&(*n).r, m, hi, x, v)
	}
	(*n).sum = sum((*n).l) + sum((*n).r)
}
func query(n *node, lo, hi, l, r int) int64 {
	if n == nil || r <= lo || hi <= l {
		return 0
	}
	if l <= lo && hi <= r {
		return n.sum
	}
	m := lo + (hi-lo)/2
	return query(n.l, lo, m, l, r) + query(n.r, m, hi, l, r)
}
func main() {
	var root *node
	add(&root, 0, size, 7, 3)
	add(&root, 0, size, 900000000, 5)
	fmt.Println(query(root, 0, size, 0, 100), query(root, 0, size, 0, size), query(root, 0, size, 7, 7))
}

