import "fmt"

type tree struct {
	n    int
	s, z []int64
}

func newTree(n int) *tree                  { return &tree{n: n, s: make([]int64, 4*n), z: make([]int64, 4*n)} }
func (t *tree) apply(i, l, r int, v int64) { t.s[i] += int64(r-l) * v; t.z[i] += v }
func (t *tree) push(i, l, r int) {
	if t.z[i] == 0 || r-l == 1 {
		return
	}
	m := l + (r-l)/2
	t.apply(i*2, l, m, t.z[i])
	t.apply(i*2+1, m, r, t.z[i])
	t.z[i] = 0
}
func (t *tree) add(i, l, r, a, b int, v int64) {
	if b <= l || r <= a {
		return
	}
	if a <= l && r <= b {
		t.apply(i, l, r, v)
		return
	}
	t.push(i, l, r)
	m := l + (r-l)/2
	t.add(i*2, l, m, a, b, v)
	t.add(i*2+1, m, r, a, b, v)
	t.s[i] = t.s[i*2] + t.s[i*2+1]
}
func (t *tree) query(i, l, r, a, b int) int64 {
	if b <= l || r <= a {
		return 0
	}
	if a <= l && r <= b {
		return t.s[i]
	}
	t.push(i, l, r)
	m := l + (r-l)/2
	return t.query(i*2, l, m, a, b) + t.query(i*2+1, m, r, a, b)
}
func main() {
	t := newTree(4)
	t.add(1, 0, 4, 0, 4, 2)
	t.add(1, 0, 4, 1, 3, 1)
	fmt.Println(t.query(1, 0, 4, 0, 4), t.query(1, 0, 4, 1, 3), t.query(1, 0, 4, 2, 2))
}

