import (
	"fmt"
	"sort"
	"strings"
)

type node struct {
	w    int
	key  rune
	l, r *node
}

func build(s string) *node {
	f := map[rune]int{}
	for _, c := range s {
		f[c]++
	}
	q := []*node{}
	for c, w := range f {
		q = append(q, &node{w: w, key: c})
	}
	for len(q) > 1 {
		sort.Slice(q, func(i, j int) bool {
			if q[i].w != q[j].w {
				return q[i].w < q[j].w
			}
			return q[i].key < q[j].key
		})
		a, b := q[0], q[1]
		k := a.key
		if b.key < k {
			k = b.key
		}
		q = append(q[2:], &node{w: a.w + b.w, key: k, l: a, r: b})
	}
	if len(q) == 0 {
		return nil
	}
	return q[0]
}
func table(n *node, p string, t map[rune]string) {
	if n == nil {
		return
	}
	if n.l == nil {
		if p == "" {
			p = "0"
		}
		t[n.key] = p
		return
	}
	table(n.l, p+"0", t)
	table(n.r, p+"1", t)
}
func encode(s string, t map[rune]string) (string, bool) {
	var b strings.Builder
	for _, c := range s {
		v, ok := t[c]
		if !ok {
			return "", false
		}
		b.WriteString(v)
	}
	return b.String(), true
}
func decode(bits string, root *node) (string, bool) {
	if root == nil {
		return "", bits == ""
	}
	var b strings.Builder
	n := root
	for _, c := range bits {
		if c != '0' && c != '1' {
			return "", false
		}
		if root.l == nil {
			if c != '0' {
				return "", false
			}
			b.WriteRune(root.key)
			continue
		}
		if c == '0' {
			n = n.l
		} else {
			n = n.r
		}
		if n.l == nil {
			b.WriteRune(n.key)
			n = root
		}
	}
	return b.String(), n == root
}
func main() {
	for _, s := range []string{"aaabbc", "zzz", ""} {
		r := build(s)
		t := map[rune]string{}
		table(r, "", t)
		bits, ok := encode(s, t)
		back, valid := decode(bits, r)
		fmt.Println(ok && valid && back == s, len(bits))
	}
	_, ok := decode("2", build("ab"))
	fmt.Println(ok)
}

