import (
	"fmt"
	"hash/fnv"
	"sort"
	"strconv"
)

type point struct {
	h           uint64
	owner, name string
}
type ring []point

func hash(s string) uint64 { h := fnv.New64a(); h.Write([]byte(s)); return h.Sum64() }
func build(owners []string, replicas int) ring {
	r := ring{}
	seen := map[string]bool{}
	for _, o := range owners {
		if seen[o] {
			continue
		}
		seen[o] = true
		for i := 0; i < replicas; i++ {
			name := o + "#" + strconv.Itoa(i)
			r = append(r, point{hash(name), o, name})
		}
	}
	sort.Slice(r, func(i, j int) bool {
		if r[i].h != r[j].h {
			return r[i].h < r[j].h
		}
		return r[i].name < r[j].name
	})
	return r
}
func (r ring) get(key string) (string, bool) {
	if len(r) == 0 {
		return "", false
	}
	h := hash(key)
	i := sort.Search(len(r), func(i int) bool { return r[i].h >= h })
	if i == len(r) {
		i = 0
	}
	return r[i].owner, true
}
func main() {
	a := build([]string{"A", "B"}, 32)
	b := build([]string{"A", "B", "C"}, 32)
	moved := 0
	for i := 0; i < 1000; i++ {
		key := strconv.Itoa(i)
		x, _ := a.get(key)
		y, _ := b.get(key)
		if x != y {
			moved++
			if y != "C" {
				panic("unrelated migration")
			}
		}
	}
	same := build([]string{"B", "A"}, 32)
	ok := true
	for i := 0; i < 1000; i++ {
		k := strconv.Itoa(i)
		x, _ := a.get(k)
		y, _ := same.get(k)
		ok = ok && x == y
	}
	_, empty := ring(nil).get("x")
	fmt.Println(moved > 0, moved < 1000, ok, empty)
}

