import (
	"fmt"
	"strconv"
)

type parser struct {
	s  string
	i  int
	ok bool
}

func (p *parser) space() {
	for p.i < len(p.s) && (p.s[p.i] == ' ' || p.s[p.i] == '\t' || p.s[p.i] == '\n') {
		p.i++
	}
}
func (p *parser) take(c byte) bool {
	p.space()
	if p.i < len(p.s) && p.s[p.i] == c {
		p.i++
		return true
	}
	return false
}
func (p *parser) atom() int {
	p.space()
	if p.take('(') {
		v := p.expr()
		if !p.take(')') {
			p.ok = false
		}
		return v
	}
	p.space()
	start := p.i
	for p.i < len(p.s) && p.s[p.i] >= '0' && p.s[p.i] <= '9' {
		p.i++
	}
	if start == p.i {
		p.ok = false
		return 0
	}
	v, e := strconv.Atoi(p.s[start:p.i])
	if e != nil {
		p.ok = false
	}
	return v
}
func (p *parser) unary() int {
	if p.take('+') {
		return p.unary()
	}
	if p.take('-') {
		return -p.unary()
	}
	return p.atom()
}
func (p *parser) term() int {
	v := p.unary()
	for p.ok {
		if p.take('*') {
			v *= p.unary()
		} else if p.take('/') {
			d := p.unary()
			if d == 0 {
				p.ok = false
				return 0
			}
			v /= d
		} else {
			break
		}
	}
	return v
}
func (p *parser) expr() int {
	v := p.term()
	for p.ok {
		if p.take('+') {
			v += p.term()
		} else if p.take('-') {
			v -= p.term()
		} else {
			break
		}
	}
	return v
}
func eval(s string) (int, bool) {
	p := parser{s: s, ok: true}
	v := p.expr()
	p.space()
	return v, p.ok && p.i == len(s)
}
func main() {
	for _, s := range []string{"2+3*(4-1)", "-(2+3)*2", "8-3-2", "-8/3"} {
		v, ok := eval(s)
		fmt.Println(v, ok)
	}
	for _, s := range []string{"8/0", "2x", "(1+2", ""} {
		_, ok := eval(s)
		fmt.Println(ok)
	}
}

