import (
	"container/list"
	"fmt"
)

type entry struct {
	k, v, f int
	e       *list.Element
}
type cache struct {
	cap, min int
	keys     map[int]*entry
	buckets  map[int]*list.List
}

func newCache(cap int) *cache {
	return &cache{cap: cap, keys: map[int]*entry{}, buckets: map[int]*list.List{}}
}
func (c *cache) bucket(f int) *list.List {
	if c.buckets[f] == nil {
		c.buckets[f] = list.New()
	}
	return c.buckets[f]
}
func (c *cache) touch(x *entry) {
	f := x.f
	b := c.buckets[f]
	b.Remove(x.e)
	if b.Len() == 0 {
		delete(c.buckets, f)
		if c.min == f {
			c.min = f + 1
		}
	}
	x.f++
	x.e = c.bucket(x.f).PushFront(x)
}
func (c *cache) get(k int) int {
	x := c.keys[k]
	if x == nil {
		return -1
	}
	c.touch(x)
	return x.v
}
func (c *cache) put(k, v int) {
	if c.cap <= 0 {
		return
	}
	if x := c.keys[k]; x != nil {
		x.v = v
		c.touch(x)
		return
	}
	if len(c.keys) == c.cap {
		b := c.buckets[c.min]
		e := b.Back()
		x := e.Value.(*entry)
		b.Remove(e)
		delete(c.keys, x.k)
		if b.Len() == 0 {
			delete(c.buckets, c.min)
		}
	}
	x := &entry{k: k, v: v, f: 1}
	x.e = c.bucket(1).PushFront(x)
	c.keys[k] = x
	c.min = 1
}
func main() {
	c := newCache(2)
	c.put(1, 10)
	c.put(2, 20)
	fmt.Println(c.get(1))
	c.put(3, 30)
	fmt.Println(c.get(2), c.get(3))
	c.put(4, 40)
	fmt.Println(c.get(1), c.get(3), c.get(4))
	z := newCache(0)
	z.put(1, 1)
	fmt.Println(z.get(1))
	c.put(4, 44)
	fmt.Println(c.get(4))
}

