import "fmt"

type node struct {
	k    int
	v    string
	n    int
	l, r *node
}

func size(x *node) int {
	if x == nil {
		return 0
	}
	return x.n
}
func put(x *node, k int, v string) *node {
	if x == nil {
		return &node{k: k, v: v, n: 1}
	}
	if k < x.k {
		x.l = put(x.l, k, v)
	} else if k > x.k {
		x.r = put(x.r, k, v)
	} else {
		x.v = v
	}
	x.n = 1 + size(x.l) + size(x.r)
	return x
}
func floor(x *node, k int) *node {
	var best *node
	for x != nil {
		if x.k == k {
			return x
		}
		if x.k < k {
			best = x
			x = x.r
		} else {
			x = x.l
		}
	}
	return best
}
func ceil(x *node, k int) *node {
	var best *node
	for x != nil {
		if x.k == k {
			return x
		}
		if x.k > k {
			best = x
			x = x.l
		} else {
			x = x.r
		}
	}
	return best
}
func selectKey(x *node, k int) *node {
	if k < 0 || k >= size(x) {
		return nil
	}
	for x != nil {
		left := size(x.l)
		if k == left {
			return x
		}
		if k < left {
			x = x.l
		} else {
			k -= left + 1
			x = x.r
		}
	}
	return nil
}
func main() {
	var r *node
	for _, k := range []int{5, 2, 8, 6} {
		r = put(r, k, "old")
	}
	r = put(r, 5, "new")
	fmt.Println(size(r), floor(r, 7).k, ceil(r, 7).k, selectKey(r, 2).k, floor(r, 1) == nil, floor(r, 5).v)
}

