import (
	"fmt"
	"sort"
)

type span [2]int

func ordered(a []span) []span {
	a = append([]span(nil), a...)
	sort.Slice(a, func(i, j int) bool {
		if a[i][0] != a[j][0] {
			return a[i][0] < a[j][0]
		}
		return a[i][1] > a[j][1]
	})
	return a
}
func merge(a []span) []span {
	out := []span{}
	for _, v := range ordered(a) {
		if len(out) == 0 || v[0] > out[len(out)-1][1] {
			out = append(out, v)
		} else if v[1] > out[len(out)-1][1] {
			out[len(out)-1][1] = v[1]
		}
	}
	return out
}
func uncovered(a []span) int {
	n, right := 0, 0
	for _, v := range ordered(a) {
		if n == 0 || v[1] > right {
			n++
			right = v[1]
		}
	}
	return n
}
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
func intersect(a, b []span) []span {
	out := []span{}
	for i, j := 0, 0; i < len(a) && j < len(b); {
		l, r := max(a[i][0], b[j][0]), min(a[i][1], b[j][1])
		if l <= r {
			out = append(out, span{l, r})
		}
		if a[i][1] < b[j][1] {
			i++
		} else {
			j++
		}
	}
	return out
}
func main() {
	fmt.Println(merge([]span{{4, 6}, {1, 4}, {8, 9}}))
	fmt.Println(uncovered([]span{{1, 3}, {1, 5}, {2, 4}, {8, 9}}))
	fmt.Println(intersect([]span{{1, 4}, {8, 9}}, []span{{4, 6}, {9, 10}}))
}
